"""Release scheduler: finds the step sequence that releases the whole batch.

The search state is (dispatched, received, active bridge); balances follow from it
exactly as the replay worker computes them (docs/replay_worker.md): a dispatch
debits the source, only a posted receipt credits the destination, and an active
bridge adds its cents to its owner's account until repaid.
"""
from collections import deque
from .authority import resolve
from .errors import ReleaseError


def plan_release(batch):
    authority = resolve(batch)
    owners = authority['owners']; payouts = authority['payouts']; bridges = authority['bridges']
    opening = {a['id']: a['balance'] for a in batch['accounts']}
    every = frozenset(p['id'] for p in payouts)
    by_bridge = {b['id']: b for b in bridges}

    def balances(dispatched, received, active):
        cash = dict(opening)
        for p in payouts:
            if p['id'] in dispatched:
                cash[owners[p['source_owner']]] -= p['cents']
            if p['id'] in received:
                cash[owners[p['destination_owner']]] += p['cents']
        if active is not None:
            cash[owners[by_bridge[active]['owner']]] += by_bridge[active]['cents']
        return cash

    start = (frozenset(), frozenset(), None)
    paths = {start: []}; queue = deque([start])
    while queue:
        state = queue.popleft(); dispatched, received, active = state
        if received == every and active is None:
            return paths[state]
        cash = balances(dispatched, received, active)
        moves = []
        for p in payouts:
            if p['id'] not in dispatched and cash[owners[p['source_owner']]] >= p['cents']:
                moves.append(('dispatch:' + p['id'], (dispatched | {p['id']}, received, active)))
            if p['id'] in dispatched and p['id'] not in received and all(x in dispatched for x in p['receipt_after']):
                moves.append(('receipt:' + p['id'], (dispatched, received | {p['id']}, active)))
        for b in bridges:
            if active is None and all(x in received for x in b['activate_after']):
                moves.append(('draw:' + b['id'], (dispatched, received, b['id'])))
            if (active == b['id'] and cash[owners[b['owner']]] >= b['cents']
                    and all(x in received for x in b['release_after'])):
                moves.append(('repay:' + b['id'], (dispatched, received, None)))
        for step, nxt in sorted(moves):
            if nxt not in paths:
                paths[nxt] = paths[state] + [step]; queue.append(nxt)
    raise ReleaseError('no schedule releases the whole batch')
